const rows = $input.first().json.rows || $input.first().json.body?.rows || [];

const contacts = [];
const companies = [];
const seenDomains = new Set();

for (const row of rows) {
  const email = (row.email || '').trim().toLowerCase();
  if (!email) continue;

  contacts.push({
    email,
    firstname: row.firstname || row.first_name || '',
    lastname: row.lastname || row.last_name || '',
    jobtitle: row.jobtitle || row.clay_title_inferred || '',
    company: row.company || row.clay_company_name || '',
    hs_lead_status: row.hs_lead_status || 'NEW',
    lifecyclestage: row.lifecyclestage || 'marketingqualifiedlead',
    icp_tier: row.icp_tier || row.clay_icp_tier || 'unscored',
    hubspot_owner_email: row.hubspot_owner_email || ''
  });

  const domain = email.split('@')[1] || '';
  if (domain && !seenDomains.has(domain)) {
    seenDomains.add(domain);
    companies.push({
      domain,
      name: row.company || row.clay_company_name || '',
      numberofemployees: row.clay_company_size || '',
      industry: row.clay_industry || ''
    });
  }
}

const eventSlug = $('Webinar Ended (webhook)').item.json.body.event_slug || 'unknown-event';
const eventTag = $('Webinar Ended (webhook)').item.json.body.event_tag || eventSlug;

return [{ json: { contacts, companies, eventSlug, eventTag } }];

const companies = $json.companies || [];
if (companies.length === 0) return [{ json: { _empty: true } }];
return companies.map(c => ({ json: c }));

const rows = $input.all().map(i => i.json).filter(r => !r._empty);
return [{ json: { inputs: rows.map(r => ({
  idProperty: 'domain',
  id: r.domain,
  properties: { domain: r.domain, name: r.name, numberofemployees: r.numberofemployees, industry: r.industry }
})) } }];

const contacts = $json.contacts || [];
if (contacts.length === 0) return [{ json: { _empty: true } }];
return contacts.map(c => ({ json: c }));

const rows = $input.all().map(i => i.json).filter(r => !r._empty);
return [{ json: { inputs: rows.map(r => ({
  idProperty: 'email',
  id: r.email,
  properties: {
    email: r.email, firstname: r.firstname, lastname: r.lastname, jobtitle: r.jobtitle,
    company: r.company, hs_lead_status: r.hs_lead_status, lifecyclestage: r.lifecyclestage,
    icp_tier: r.icp_tier, hubspot_owner_email: r.hubspot_owner_email
  }
})) } }];

const items = $input.all().map(i => i.json);
const contactResults = items.filter(i => i.properties && i.properties.email);
const companyResults = items.filter(i => i.properties && i.properties.domain);

const idByDomain = {};
for (const co of companyResults) idByDomain[co.properties.domain] = co.id;

const pairs = [];
for (const c of contactResults) {
  const domain = (c.properties.email.split('@')[1] || '').toLowerCase();
  const companyId = idByDomain[domain];
  if (companyId) pairs.push({ from: { id: c.id }, to: { id: companyId } });
}

if (pairs.length === 0) return [{ json: { _empty: true } }];
return pairs.map(p => ({ json: p }));

return [{ json: {
  status: 'blocked',
  reason: 'human approval was not granted (body.approved was not true)',
  event_slug: $('Shape M1 Payload').item.json.eventSlug,
  event_tag: $('Shape M1 Payload').item.json.eventTag,
  blocked_at: new Date().toISOString()
} }];

const item = $input.first();
const err = item.json.error || item.json;
return [{ json: {
  status: 'error',
  failing_node: $prevNode?.name || 'unknown',
  message: (err && (err.message || err.description)) || JSON.stringify(err).slice(0, 500),
  event_slug: ($('Shape M1 Payload').first()?.json?.eventSlug) || 'unknown-event',
  execution_id: $execution.id,
  failed_at: new Date().toISOString()
} }];
